package com.troday.api.service;
import com.fasterxml.jackson.databind.JsonNode; import com.troday.api.dto.ApiResponseDto; import com.troday.api.entity.*; import com.troday.api.repository.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.transaction.Transactional; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*;
@Service public class ContractChangeService {
 @org.springframework.beans.factory.annotation.Autowired private DomainSupport domain;
 private final AccountService accounts; private final ContractRepository contracts; private final ContractChangeRequestRepository changes; private final RoomRepository rooms;
 public ContractChangeService(AccountService a,ContractRepository c,ContractChangeRequestRepository x,RoomRepository rooms){accounts=a;contracts=c;changes=x;this.rooms=rooms;}
 public ApiResponseDto<?> list(HttpServletRequest r,Long cid){access(r,cid);return ok("GET",changes.findByContractIdOrderByIdDesc(cid).stream().map(this::data).toList());}
 @Transactional public ApiResponseDto<?> create(HttpServletRequest r,Long cid,JsonNode b){Long me=accounts.authenticatedUserId(r);domain.lockContract(cid);Contract c=access(r,cid);if(!domain.representative(c.getId(),me))throw forbidden("Chỉ đại diện mới được yêu cầu điều chỉnh");if(!"ACTIVE".equals(c.getStatus()))throw conflict("Chỉ hợp đồng ACTIVE mới được điều chỉnh");String type=text(b,"type");if(!Set.of("RENEWAL","TERMINATION","TRANSFER").contains(type))throw bad("type không hợp lệ");Long base=requiredLong(b,"baseRevisionId");if(!Objects.equals(c.getCurrentRevisionId(),base))throw conflict("Revision nền đã thay đổi");if(changes.findByContractIdOrderByIdDesc(cid).stream().anyMatch(x->Set.of("PENDING","APPROVED_WAITING_CONFIRMATION","READY_TO_APPLY").contains(x.getStatus())))throw conflict("Đã có yêu cầu điều chỉnh đang mở");Long target=b.hasNonNull("targetRoomId")?b.get("targetRoomId").asLong():null;if("TRANSFER".equals(type)&&target==null)throw bad("targetRoomId là bắt buộc khi đổi phòng");if(!"TRANSFER".equals(type)&&target!=null)throw bad("targetRoomId chỉ dùng cho TRANSFER");ContractChangeRequest x=new ContractChangeRequest();x.setContractId(cid);x.setRequestedById(me);x.setRepresentativeRoomTenantId(c.getRepresentativeRoomTenantId());x.setBaseRevisionId(base);x.setTargetRoomId(target);x.setType(type);x.setRequestedEffectiveDate(date(b,"effectiveDate"));com.fasterxml.jackson.databind.node.ObjectNode proposal=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();proposal.put("reason",text(b,"reason"));
        if(text(b,"reason").isBlank())throw bad("Cần lý do điều chỉnh");
        if("RENEWAL".equals(type)){LocalDate end=date(b,"newEndDate");if(!end.isAfter(c.getEndDate()))throw bad("Ngày kết thúc mới phải sau ngày kết thúc cũ");proposal.put("newEndDate",end.toString());}
        if("TRANSFER".equals(type)){JsonNode terms=b.path("proposal");if(terms.path("content").asText().isBlank()||terms.path("endDate").asText().isBlank())throw bad("Phương án chuyển phòng cần content và endDate");if(!domain.exists("SELECT r.id FROM rooms r JOIN rental_houses h ON h.id=r.house_id WHERE r.id=? AND h.landlord_id=?",target,c.getLandlordId()))throw bad("Phòng đích phải cùng chủ");proposal.put("content",terms.path("content").asText());proposal.put("end_date",terms.path("endDate").asText());if(terms.hasNonNull("rentAmount"))proposal.set("rent_amount",terms.get("rentAmount"));if(terms.hasNonNull("depositAmount"))proposal.set("deposit_amount",terms.get("depositAmount"));}
        if(x.getRequestedEffectiveDate().isBefore(c.getStartDate()))throw bad("Ngày hiệu lực không trước ngày bắt đầu");x.setProposalSnapshot(proposal.toString());x.setMessage(text(b,"reason"));return ok("POST",data(changes.save(x)));}
 public ApiResponseDto<?> detail(HttpServletRequest r,Long id){ContractChangeRequest x=change(id);access(r,x.getContractId());return ok("GET",data(x));}
 @Transactional public ApiResponseDto<?> decision(HttpServletRequest r,Long id,JsonNode b){Long owner=accounts.authenticatedUserId(r);domain.lockContract(domain.jdbc.queryForObject("SELECT contract_id FROM contract_change_requests WHERE id=?",Long.class,id));domain.jdbc.queryForList("SELECT id FROM contract_change_requests WHERE id=? FOR UPDATE",id);ContractChangeRequest x=change(id);Contract c=access(r,x.getContractId());if(!Objects.equals(c.getLandlordId(),owner))throw forbidden("Chỉ chủ trọ được duyệt");if(!"PENDING".equals(x.getStatus()))throw conflict("Yêu cầu không còn chờ");String d=text(b,"decision");if(!Set.of("APPROVE","REJECT").contains(d))throw bad("decision phải là APPROVE hoặc REJECT");x.setReviewedById(owner);x.setReviewedAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));if("REJECT".equals(d)){x.setStatus("REJECTED");x.setRejectionReason(text(b,"reason"));if(x.getRejectionReason().isBlank())throw bad("reason là bắt buộc");}else{if(!Objects.equals(c.getCurrentRevisionId(),x.getBaseRevisionId())||!Objects.equals(c.getRepresentativeRoomTenantId(),x.getRepresentativeRoomTenantId()))throw conflict("Revision hoặc đại diện đã thay đổi");
            if("RENEWAL".equals(x.getType())){Long rev=domain.jdbc.queryForObject("SELECT COALESCE(MAX(revision_number),0)+1 FROM contract_revisions WHERE contract_id=?",Long.class,c.getId());String end;try{end=new com.fasterxml.jackson.databind.ObjectMapper().readTree(x.getProposalSnapshot()).path("newEndDate").asText();}catch(Exception e){throw bad("Phương án không hợp lệ");}
                org.springframework.jdbc.support.GeneratedKeyHolder keys=new org.springframework.jdbc.support.GeneratedKeyHolder();domain.jdbc.update(connection->{var stmt=connection.prepareStatement("INSERT INTO contract_revisions(contract_id,revision_number,created_by_id,kind,status,start_date,end_date,effective_from,rent_amount,deposit_amount,content,members_snapshot,representative_room_tenant_id,landlord_confirmed_by_id,landlord_confirmed_at,sent_at) SELECT contract_id,?,?,'RENEWAL','PENDING_CONFIRMATION',start_date,?,?,rent_amount,deposit_amount,content,members_snapshot,representative_room_tenant_id,?,UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM contract_revisions WHERE id=?",java.sql.Statement.RETURN_GENERATED_KEYS);stmt.setObject(1,rev);stmt.setObject(2,owner);stmt.setObject(3,end);stmt.setObject(4,x.getRequestedEffectiveDate());stmt.setObject(5,owner);stmt.setObject(6,c.getCurrentRevisionId());return stmt;},keys);x.setProposedRevisionId(keys.getKey().longValue());}
            x.setStatus("APPROVED_WAITING_CONFIRMATION");x.setExpiresAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS).plusDays(2));}return ok("POST",data(changes.save(x)));}
 @Transactional public ApiResponseDto<?> confirm(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);domain.lockContract(domain.jdbc.queryForObject("SELECT contract_id FROM contract_change_requests WHERE id=?",Long.class,id));domain.jdbc.queryForList("SELECT id FROM contract_change_requests WHERE id=? FOR UPDATE",id);ContractChangeRequest x=change(id);Contract c=access(r,x.getContractId());if(!domain.representative(c.getId(),me))throw forbidden("Chỉ đại diện mới được xác nhận");if(!"APPROVED_WAITING_CONFIRMATION".equals(x.getStatus()))throw conflict("Yêu cầu chưa được chủ trọ duyệt");if(x.getExpiresAt()!=null&&x.getExpiresAt().isBefore(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS)))throw conflict("Phương án đã hết hạn");if(!Objects.equals(c.getCurrentRevisionId(),x.getBaseRevisionId())||!Objects.equals(c.getRepresentativeRoomTenantId(),x.getRepresentativeRoomTenantId()))throw conflict("Revision hoặc đại diện đã thay đổi");if(!Objects.equals(text(b,"proposalHash"),proposalHash(x)))throw conflict("Phương án đã thay đổi; hãy đọc lại trước khi xác nhận");if("RENEWAL".equals(x.getType())){if(!Objects.equals(requiredLong(b,"proposedRevisionId"),x.getProposedRevisionId()))throw conflict("Revision đề xuất đã thay đổi");domain.jdbc.update("UPDATE contract_revisions SET status='CONFIRMED',tenant_confirmed_by_id=?,tenant_confirmed_at=UTC_TIMESTAMP(6) WHERE id=? AND status='PENDING_CONFIRMATION'",me,x.getProposedRevisionId());}x.setStatus("READY_TO_APPLY");x.setTenantConfirmedById(me);x.setTenantConfirmedAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));return ok("POST",data(changes.save(x)));}
 @Transactional public ApiResponseDto<?> cancel(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);ContractChangeRequest x=change(id);if(!Objects.equals(x.getRequestedById(),me))throw forbidden("Chỉ người yêu cầu mới được hủy");if(!Set.of("PENDING","APPROVED_WAITING_CONFIRMATION","READY_TO_APPLY").contains(x.getStatus()))throw conflict("Yêu cầu không thể hủy");x.setStatus("CANCELLED");x.setCancelledById(me);x.setCancelledAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));x.setCancellationReason(text(b,"reason"));return ok("POST",data(changes.save(x)));}
 public ApiResponseDto<?> apply(HttpServletRequest r,Long id){
ContractChangeRequest x=change(id);access(r,x.getContractId());domain.procedure("sp_apply_contract_change",true,id,accounts.authenticatedUserId(r));return ok("POST",data(change(id)));
 }
 public ApiResponseDto<?> transferOptions(HttpServletRequest r,Long cid){
Contract c=access(r,cid);return ok("GET",domain.jdbc.queryForList("SELECT r.id AS roomId,r.house_id AS houseId,r.room_number AS code,r.area,r.rent_price AS rentAmount,r.deposit_amount AS depositAmount,r.max_occupants AS capacity,(SELECT COUNT(*) FROM room_tenants WHERE contract_id=? AND status IN ('ACTIVE','PLANNED')) AS openMemberCount FROM rooms r JOIN rental_houses h ON h.id=r.house_id JOIN v_effective_house_verifications v ON v.house_id=h.id WHERE h.landlord_id=? AND r.id<>? AND r.status='AVAILABLE' AND r.max_occupants>=(SELECT COUNT(*) FROM room_tenants WHERE contract_id=? AND status IN ('ACTIVE','PLANNED')) AND NOT EXISTS(SELECT 1 FROM contracts c2 WHERE c2.room_id=r.id AND c2.status IN ('DRAFT','PENDING_CONFIRMATION','CONFIRMED','ACTIVE'))",cid,c.getLandlordId(),c.getRoomId(),cid));
 }
 private String proposalHash(ContractChangeRequest x){try{com.fasterxml.jackson.databind.ObjectMapper mapper=new com.fasterxml.jackson.databind.ObjectMapper();var node=mapper.readTree(x.getProposalSnapshot());java.util.TreeMap<String,Object> canonical=mapper.convertValue(node,new com.fasterxml.jackson.core.type.TypeReference<java.util.TreeMap<String,Object>>(){});String value=domain.json(canonical)+":"+x.getBaseRevisionId()+":"+x.getRepresentativeRoomTenantId()+":"+x.getRequestedEffectiveDate()+":"+x.getProposedRevisionId();return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private Contract access(HttpServletRequest r,Long id){Long me=accounts.authenticatedUserId(r);Contract c=contracts.findById(id).orElseThrow(()->notFound("Không tìm thấy hợp đồng"));if(!domain.contractReader(id,me))throw forbidden("Không có quyền với hợp đồng");return c;}private ContractChangeRequest change(Long id){return changes.findById(id).orElseThrow(()->notFound("Không tìm thấy yêu cầu điều chỉnh"));}private LocalDate date(JsonNode b,String k){try{return LocalDate.parse(text(b,k));}catch(Exception e){throw bad(k+" không hợp lệ");}}private Long requiredLong(JsonNode b,String k){if(b==null||!b.hasNonNull(k))throw bad(k+" là bắt buộc");return b.get(k).asLong();}private String text(JsonNode b,String k){return b!=null&&b.hasNonNull(k)?b.get(k).asText():"";}
 private Map<String,Object> data(ContractChangeRequest x){Map<String,Object>m=new LinkedHashMap<>();m.put("id",x.getId());m.put("contractId",x.getContractId());m.put("type",x.getType());m.put("status",x.getStatus());m.put("requestedById",x.getRequestedById());m.put("baseRevisionId",x.getBaseRevisionId());m.put("targetRoomId",x.getTargetRoomId());m.put("resultContractId",x.getResultContractId());m.put("requestedEffectiveDate",x.getRequestedEffectiveDate());m.put("proposalSnapshot",x.getProposalSnapshot());m.put("proposalHash",proposalHash(x));m.put("proposedRevisionId",x.getProposedRevisionId());m.put("rejectionReason",x.getRejectionReason());return m;}private ApiResponseDto<?> ok(String m,Object d){return ApiResponseDto.ok("/api/v1",m,d);}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,m);}private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);}private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
